import{_ as o,a0 as i,w as a,s as r,ao as p,I as n,a1 as u,A as m,x as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble | LCTT x X-CMD","titleTemplate":false,"description":"遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps","title":"遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble","tag":"201504","desc":""},"relativePath":"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps.md","filePath":"[post].md"}'),b={name:"201504/20150211 Install Mumble in Ubuntu an Opensource VoIP Apps.md"};function s(d,e,g,x,T,f){const t=i("Link");return a(),r("div",null,[e[15]||(e[15]=p('<h1 id="遊戲玩家的福音-在-ubuntu-上安裝開源-voip-應用-mumble" tabindex="-1">遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble <a class="header-anchor" href="#遊戲玩家的福音-在-ubuntu-上安裝開源-voip-應用-mumble" aria-label="Permalink to “遊戲玩家的福音：在 Ubuntu 上安裝開源 VoIP 應用 Mumble”">​</a></h1><p>Mumble是一個自由開源的VoIP應用，在新的 BSD 許可證下發布，主要面向的用户羣體是遊戲玩家。運行起來類似於TeamSpeak和Ventrilo，用户通過連接到同一個服務器來實現相互通訊。</p><p>Mumble提供瞭如下的漂亮特性:</p><ul><li>低延遲，這點對遊戲相當重要</li><li>提供遊戲中的可視插件，通過它你可以知道是誰正在和你通話並定位他們的位置</li><li>交談內容經過加密的，能夠保護你的隱私和安全</li><li>界面簡單易於上手</li><li>穩定高效的使用你的服務器資源</li></ul><h3 id="安裝-mumble" tabindex="-1">安裝 Mumble <a class="header-anchor" href="#安裝-mumble" aria-label="Permalink to “安裝 Mumble”">​</a></h3>',5)),n("p",null,[u(t,{href:"http://wiki.mumble.info/wiki/Main_Page"},{default:m(()=>[...e[0]||(e[0]=[l("Mumble",-1)])]),_:1}),e[1]||(e[1]=l("已經流行開來，進入了許多linux主流發行版的軟件倉庫，這使它安裝起來更加的方便。若你使用的是Ubuntu那麼使用apt-get就能安裝，詳細命令如下：",-1))]),e[16]||(e[16]=p(`<pre><code>$ sudo apt-get install mumble-server
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-install.jpg" alt="mumble install"></p><p>這條命令將會在你的服務器上安裝服務端（亦稱Murmur）。</p><h3 id="配置-mumble" tabindex="-1">配置 Mumble <a class="header-anchor" href="#配置-mumble" aria-label="Permalink to “配置 Mumble”">​</a></h3><p>運行以下命令啓動Mumble：</p><pre><code>$ sudo dpkg-reconfigure mumble-server
</code></pre><p>會彈出以下一些問題：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q1.jpg" alt="mumble q1"></p><p>選擇“是”讓服務器開機時自動啓動mumble，接着它會詢問你是否運行高優先級模式以保持低延遲，為了讓它保持最佳性能這是個不錯的主意。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q2.jpg" alt="mumble q2"></p><p>接着為你剛安裝好的mumble服務端設管理員用户的密碼，記住這個密碼，它會在登錄時用到。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-q3.jpg" alt="mumble q3"></p><h3 id="安裝-mumble-客户端" tabindex="-1">安裝 Mumble 客户端 <a class="header-anchor" href="#安裝-mumble-客户端" aria-label="Permalink to “安裝 Mumble 客户端”">​</a></h3><p>客户端可以安裝到許多的主流操作系統中，例如windows，mac和linux。我們將教你在Ubuntu linux上安裝和配置，你可以使用軟件中心也可以用命令安裝客户端：</p><pre><code>$ sudo apt-get install mumble
</code></pre><p>第一次運行mumble時，配置嚮導將會幫助你配置音頻的輸入輸出，使其能在客户端上保持最好的效果。第一次同樣也會詢問你要使用的是什麼聲音設備和麥克風：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-1.jpg" alt="mumble client 1"></p><p>然後它將幫你校準設備：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-2.jpg" alt="mumble client 2"></p><p>因為mumble會幫你加密所有的通訊內容所以它會要求你創建證書：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-client-3.jpg" alt="mumble client 3"></p><p>完成配置嚮導後你就能添加第一個服務器，連接對話框如下圖所示：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/01/mumble-add-server.jpg" alt="mumble add server"></p><p>首先輸入一個標籤，名字任意因為那隻不過是為了記住服務器的，然後輸入服務器的地址和端口，最後使用“SuperUser”作為用户名，而密碼則是你配置mumble服務器端時輸入的密碼。</p><p>現在你可以連接到服務器了，在聯網玩遊戲或與你好友、隊友聊天開黑時享受這些功能給你帶來的樂趣吧！</p><hr>`,26)),n("p",null,[e[3]||(e[3]=l("via: ",-1)),u(t,{href:"http://linoxide.com/ubuntu-how-to/install-mumble-ubuntu/"},{default:m(()=>[...e[2]||(e[2]=[l("http://linoxide.com/ubuntu-how-to/install-mumble-ubuntu/",-1)])]),_:1})]),n("p",null,[e[7]||(e[7]=l("作者：",-1)),u(t,{href:"http://linoxide.com/author/adriand/"},{default:m(()=>[...e[4]||(e[4]=[l("Adrian Dinu",-1)])]),_:1}),e[8]||(e[8]=l(" 譯者：",-1)),u(t,{href:"https://github.com/martin2011qi"},{default:m(()=>[...e[5]||(e[5]=[l("martin2011qi",-1)])]),_:1}),e[9]||(e[9]=l(" 校對：",-1)),u(t,{href:"https://github.com/wxy"},{default:m(()=>[...e[6]||(e[6]=[l("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=l("本文由 ",-1)),u(t,{href:"https://github.com/LCTT/TranslateProject"},{default:m(()=>[...e[10]||(e[10]=[l("LCTT",-1)])]),_:1}),e[13]||(e[13]=l(" 原創翻譯，",-1)),u(t,{href:"http://linux.cn/"},{default:m(()=>[...e[11]||(e[11]=[l("Linux中國",-1)])]),_:1}),e[14]||(e[14]=l(" 榮譽推出",-1))])])}const I=o(b,[["render",s]]);export{h as __pageData,I as default};
